import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Panel and moderation","description":"","frontmatter":{"pageId":"admins/administration","contentRevision":2},"headers":[],"relativePath":"en/admins/administration.md","filePath":"en/admins/administration.md"}'),i={name:"en/admins/administration.md"};function o(s,e,l,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="panel-and-moderation" tabindex="-1">Panel and moderation <a class="header-anchor" href="#panel-and-moderation" aria-label="Permalink to &quot;Panel and moderation&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Open HTTPS /admin/ and sign in with legacy Admin:ApiToken. The panel exposes players, status, economy, raids and audit history. Use a separate API token for integrations rather than copying a cookie.</p><p>Start by reading player/status/actions and confirming IDs. Kick disconnects; mute restricts chat; ban denies login; economy freeze and raids freeze control separate subsystems. Record reasons in the audit.</p><p>Rollback selects a specific save version; reset creates a new colony timeline and clears related permissions. Archive retains a colony separately; restore-colony restores it subject to context checks. Coop rollback clears pawn assignments; revocation ends its session. Administrators may withdraw influence with an expected version, but cannot enable it for a player.</p><h2 id="moderation-case" tabindex="-1">Investigate a missing-transfer report <a class="header-anchor" href="#moderation-case" aria-label="Permalink to &quot;Investigate a missing-transfer report {#moderation-case}&quot;">​</a></h2><p>Find the player by exact name/#id, inspect the card and correlate persistent IDs, not display names alone. Match report time with actions, parcels, lots/trades and wallet debits. Determine whether client snapshot/replay finished. Read-only tokens redact private fields; missing data there does not mean no account exists.</p><p>Read first, then perform one suitable action with a reason: trade cancellation, lot/parcel refund or moderation. Verify its result and delivery. Never combine colony rollback and manual compensation without reconciling server economy.</p><h2 id="admin-danger" tabindex="-1">Choose rollback, reset or archive <a class="header-anchor" href="#admin-danger" aria-label="Permalink to &quot;Choose rollback, reset or archive {#admin-danger}&quot;">​</a></h2><p>Rollback selects an older map version and advances the write epoch. Reset begins a new colony lifetime and revokes related permissions. Archive frees an offline colony tile with a separate record; restore-colony needs a free tile and intact archive. Recreateworld is not a single-pawn repair.</p><p>Obtain confirmation, a consistent backup and a notification plan before destructive actions. After rollback require menu/relogin; after reset reject the separated old save. Other players&#39; settled state does not rewind merely because an old map returned.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Reset, rollback, recreateworld and restore have destructive consequences: obtain confirmation and a verified backup first. Do not compensate a failure with wallet +n before inspecting escrow. Unfreezing does not repair a damaged save.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./cli">CLI reference</a></li><li><a href="./api">REST API reference</a></li><li><a href="./backup-recovery">Backup and recovery</a></li></ul>',16)])])}const f=a(i,[["render",o]]);export{h as __pageData,f as default};
